-- WASSCE Elective Mathematics 2023 Questions (50 questions)

INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, total_questions, total_marks, time_allowed, is_complete)
VALUES ('pp_wassce_em_2023_1', 'exam_wassce', 'subj_wassce_elect_math', 'paper_wassce_1', 2023, 'May-June', 50, 50, 60, 1);

INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Calculus (1-15)
('q_em_2023_001', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If y = 3x⁴, find dy/dx:', 'multiple_choice', '["A. 12x³", "B. 3x³", "C. 12x⁴", "D. 3x⁵"]', 'A', 'Using the power rule: dy/dx = 4 × 3x³ = 12x³.', 'easy', 1, 1),
('q_em_2023_002', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The derivative of sin x is:', 'multiple_choice', '["A. -cos x", "B. cos x", "C. -sin x", "D. tan x"]', 'B', 'd/dx(sin x) = cos x.', 'easy', 1, 2),
('q_em_2023_003', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Find ∫2x dx:', 'multiple_choice', '["A. x² + C", "B. 2x² + C", "C. x + C", "D. 2 + C"]', 'A', '∫2x dx = 2(x²/2) + C = x² + C.', 'easy', 1, 3),
('q_em_2023_004', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If f(x) = x³ - 3x, find f''(x):', 'multiple_choice', '["A. 3x² - 3", "B. 6x", "C. 3x² + 3", "D. 6x - 3"]', 'B', 'f''(x) = 3x² - 3, so f''''(x) = 6x.', 'medium', 1, 4),
('q_em_2023_005', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The stationary points of a function occur where:', 'multiple_choice', '["A. f(x) = 0", "B. f''(x) = 0", "C. f''''(x) = 0", "D. f(x) = 1"]', 'B', 'Stationary points occur where the first derivative equals zero (f''(x) = 0).', 'easy', 1, 5),
('q_em_2023_006', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', '∫cos x dx =', 'multiple_choice', '["A. sin x + C", "B. -sin x + C", "C. cos x + C", "D. -cos x + C"]', 'A', 'The integral of cos x is sin x + C.', 'easy', 1, 6),
('q_em_2023_007', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If y = eˣ, then dy/dx =', 'multiple_choice', '["A. xeˣ⁻¹", "B. eˣ", "C. xe", "D. eˣ⁺¹"]', 'B', 'The derivative of eˣ is eˣ itself.', 'easy', 1, 7),
('q_em_2023_008', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Find dy/dx if y = ln x:', 'multiple_choice', '["A. 1/x", "B. x", "C. ln x", "D. 1/ln x"]', 'A', 'd/dx(ln x) = 1/x.', 'easy', 1, 8),
('q_em_2023_009', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Evaluate ∫₀² 3x² dx:', 'multiple_choice', '["A. 6", "B. 8", "C. 12", "D. 24"]', 'B', '∫₀² 3x² dx = [x³]₀² = 8 - 0 = 8.', 'medium', 1, 9),
('q_em_2023_010', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Using the chain rule, if y = (2x+1)³, find dy/dx:', 'multiple_choice', '["A. 3(2x+1)²", "B. 6(2x+1)²", "C. 2(2x+1)³", "D. 6(2x+1)³"]', 'B', 'dy/dx = 3(2x+1)² × 2 = 6(2x+1)².', 'medium', 1, 10),
('q_em_2023_011', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The maximum value of f(x) = -x² + 4x + 5 is:', 'multiple_choice', '["A. 5", "B. 7", "C. 9", "D. 11"]', 'C', 'f''(x) = -2x + 4 = 0, so x = 2. f(2) = -4 + 8 + 5 = 9.', 'medium', 1, 11),
('q_em_2023_012', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', '∫1/x dx =', 'multiple_choice', '["A. x + C", "B. ln x + C", "C. -1/x² + C", "D. ln|x| + C"]', 'D', '∫1/x dx = ln|x| + C (absolute value for all x ≠ 0).', 'medium', 1, 12),
('q_em_2023_013', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If y = x² sin x, use the product rule to find dy/dx:', 'multiple_choice', '["A. 2x sin x + x² cos x", "B. 2x cos x", "C. x² cos x", "D. 2x sin x - x² cos x"]', 'A', 'Product rule: dy/dx = 2x sin x + x² cos x.', 'hard', 1, 13),
('q_em_2023_014', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The area under the curve y = x² from x = 0 to x = 3 is:', 'multiple_choice', '["A. 3", "B. 6", "C. 9", "D. 27"]', 'C', 'Area = ∫₀³ x² dx = [x³/3]₀³ = 27/3 = 9.', 'medium', 1, 14),
('q_em_2023_015', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If f''''(x) > 0 at a stationary point, the point is a:', 'multiple_choice', '["A. Maximum", "B. Minimum", "C. Point of inflection", "D. Saddle point"]', 'B', 'If f''''(x) > 0 at a stationary point, the curve is concave up, indicating a minimum.', 'medium', 1, 15),

-- Coordinate Geometry and Vectors (16-25)
('q_em_2023_016', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The distance between points (1, 2) and (4, 6) is:', 'multiple_choice', '["A. 3", "B. 4", "C. 5", "D. 7"]', 'C', 'd = √[(4-1)² + (6-2)²] = √[9 + 16] = √25 = 5.', 'easy', 1, 16),
('q_em_2023_017', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The midpoint of the line segment joining (2, 4) and (6, 8) is:', 'multiple_choice', '["A. (4, 6)", "B. (3, 5)", "C. (4, 4)", "D. (8, 12)"]', 'A', 'Midpoint = ((2+6)/2, (4+8)/2) = (4, 6).', 'easy', 1, 17),
('q_em_2023_018', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The gradient of the line passing through (1, 3) and (3, 7) is:', 'multiple_choice', '["A. 1", "B. 2", "C. 3", "D. 4"]', 'B', 'Gradient = (7-3)/(3-1) = 4/2 = 2.', 'easy', 1, 18),
('q_em_2023_019', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The equation of a circle with center (0, 0) and radius 5 is:', 'multiple_choice', '["A. x² + y² = 5", "B. x² + y² = 25", "C. x + y = 5", "D. (x-5)² + (y-5)² = 25"]', 'B', 'Circle equation: x² + y² = r² = 5² = 25.', 'easy', 1, 19),
('q_em_2023_020', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Two lines are perpendicular if the product of their gradients is:', 'multiple_choice', '["A. 0", "B. 1", "C. -1", "D. 2"]', 'C', 'Perpendicular lines have gradients m₁ and m₂ where m₁ × m₂ = -1.', 'easy', 1, 20),
('q_em_2023_021', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If a = 3i + 4j, the magnitude of a is:', 'multiple_choice', '["A. 7", "B. 5", "C. 12", "D. 1"]', 'B', '|a| = √(3² + 4²) = √(9 + 16) = √25 = 5.', 'easy', 1, 21),
('q_em_2023_022', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The dot product of a = 2i + 3j and b = 4i - 2j is:', 'multiple_choice', '["A. 2", "B. 8", "C. 14", "D. -2"]', 'A', 'a · b = (2)(4) + (3)(-2) = 8 - 6 = 2.', 'medium', 1, 22),
('q_em_2023_023', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The position vector of point P(3, -2) is:', 'multiple_choice', '["A. 3i + 2j", "B. 3i - 2j", "C. -3i + 2j", "D. -3i - 2j"]', 'B', 'Position vector OP = 3i - 2j (from origin to point P).', 'easy', 1, 23),
('q_em_2023_024', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If vectors a and b are perpendicular, then a · b =', 'multiple_choice', '["A. 1", "B. -1", "C. 0", "D. |a||b|"]', 'C', 'Perpendicular vectors have dot product equal to zero.', 'easy', 1, 24),
('q_em_2023_025', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The unit vector in the direction of 3i + 4j is:', 'multiple_choice', '["A. 3i + 4j", "B. (3/5)i + (4/5)j", "C. (3/7)i + (4/7)j", "D. i + j"]', 'B', 'Unit vector = (3i + 4j)/5 = (3/5)i + (4/5)j.', 'medium', 1, 25),

-- Trigonometry (26-35)
('q_em_2023_026', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'sin 30° =', 'multiple_choice', '["A. 0", "B. 1/2", "C. √3/2", "D. 1"]', 'B', 'sin 30° = 1/2 (standard trigonometric value).', 'easy', 1, 26),
('q_em_2023_027', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'cos 60° =', 'multiple_choice', '["A. 0", "B. 1/2", "C. √3/2", "D. 1"]', 'B', 'cos 60° = 1/2 (complementary to sin 30°).', 'easy', 1, 27),
('q_em_2023_028', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'tan 45° =', 'multiple_choice', '["A. 0", "B. 1", "C. √2", "D. undefined"]', 'B', 'tan 45° = sin 45°/cos 45° = 1.', 'easy', 1, 28),
('q_em_2023_029', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The identity sin²θ + cos²θ equals:', 'multiple_choice', '["A. 0", "B. 1", "C. 2", "D. sin 2θ"]', 'B', 'The Pythagorean identity: sin²θ + cos²θ = 1 for all θ.', 'easy', 1, 29),
('q_em_2023_030', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'Convert 180° to radians:', 'multiple_choice', '["A. π/2", "B. π", "C. 2π", "D. π/4"]', 'B', '180° = π radians.', 'easy', 1, 30),
('q_em_2023_031', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The period of sin x is:', 'multiple_choice', '["A. π", "B. 2π", "C. π/2", "D. 4π"]', 'B', 'The sine function has a period of 2π radians (or 360°).', 'easy', 1, 31),
('q_em_2023_032', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'sin 2θ equals:', 'multiple_choice', '["A. 2 sin θ", "B. 2 sin θ cos θ", "C. sin²θ", "D. cos 2θ"]', 'B', 'Double angle formula: sin 2θ = 2 sin θ cos θ.', 'medium', 1, 32),
('q_em_2023_033', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'In a triangle, if a = 5, b = 7, and C = 60°, find c using cosine rule:', 'multiple_choice', '["A. √39", "B. √37", "C. 6", "D. 8"]', 'A', 'c² = a² + b² - 2ab cos C = 25 + 49 - 2(5)(7)(0.5) = 74 - 35 = 39. c = √39.', 'hard', 1, 33),
('q_em_2023_034', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'sec θ equals:', 'multiple_choice', '["A. 1/sin θ", "B. 1/cos θ", "C. 1/tan θ", "D. sin θ/cos θ"]', 'B', 'sec θ = 1/cos θ (secant is reciprocal of cosine).', 'easy', 1, 34),
('q_em_2023_035', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The general solution of sin θ = 1/2 is:', 'multiple_choice', '["A. θ = 30° + 360n°", "B. θ = 30° + 360n° or 150° + 360n°", "C. θ = 60° + 180n°", "D. θ = 45° + 360n°"]', 'B', 'sin θ = 1/2 has solutions at 30° and 150° in [0°, 360°], with period 360°.', 'hard', 1, 35),

-- Probability and Statistics (36-45)
('q_em_2023_036', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If P(A) = 0.3 and P(B) = 0.4, and A and B are independent, P(A ∩ B) =', 'multiple_choice', '["A. 0.7", "B. 0.12", "C. 0.1", "D. 0.7"]', 'B', 'For independent events: P(A ∩ B) = P(A) × P(B) = 0.3 × 0.4 = 0.12.', 'medium', 1, 36),
('q_em_2023_037', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The number of ways to arrange 5 different books on a shelf is:', 'multiple_choice', '["A. 5", "B. 25", "C. 120", "D. 625"]', 'C', '5! = 5 × 4 × 3 × 2 × 1 = 120 arrangements.', 'easy', 1, 37),
('q_em_2023_038', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'In how many ways can 3 people be chosen from 7?', 'multiple_choice', '["A. 21", "B. 35", "C. 210", "D. 343"]', 'B', '⁷C₃ = 7!/(3!4!) = (7×6×5)/(3×2×1) = 35.', 'medium', 1, 38),
('q_em_2023_039', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The mean of 2, 4, 6, 8, 10 is:', 'multiple_choice', '["A. 5", "B. 6", "C. 7", "D. 8"]', 'B', 'Mean = (2+4+6+8+10)/5 = 30/5 = 6.', 'easy', 1, 39),
('q_em_2023_040', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The variance of a data set measures:', 'multiple_choice', '["A. Central tendency", "B. Spread of data", "C. Mode", "D. Median"]', 'B', 'Variance measures the spread or dispersion of data around the mean.', 'easy', 1, 40),
('q_em_2023_041', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'If P(A) = 0.6, then P(A'') =', 'multiple_choice', '["A. 0.6", "B. 0.4", "C. 1", "D. 0"]', 'B', 'P(A'') = 1 - P(A) = 1 - 0.6 = 0.4.', 'easy', 1, 41),
('q_em_2023_042', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The standard deviation is the:', 'multiple_choice', '["A. Square of variance", "B. Square root of variance", "C. Half of variance", "D. Double of variance"]', 'B', 'Standard deviation = √variance.', 'easy', 1, 42),
('q_em_2023_043', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'For mutually exclusive events A and B, P(A ∪ B) =', 'multiple_choice', '["A. P(A) × P(B)", "B. P(A) + P(B)", "C. P(A) - P(B)", "D. P(A)/P(B)"]', 'B', 'For mutually exclusive events: P(A ∪ B) = P(A) + P(B).', 'medium', 1, 43),
('q_em_2023_044', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The coefficient of x³ in (1+x)⁵ is:', 'multiple_choice', '["A. 5", "B. 10", "C. 15", "D. 20"]', 'B', '⁵C₃ = 10 (binomial coefficient for x³ term).', 'medium', 1, 44),
('q_em_2023_045', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'A fair die is rolled. P(getting a number > 4) =', 'multiple_choice', '["A. 1/6", "B. 1/3", "C. 1/2", "D. 2/3"]', 'B', 'Numbers > 4 are 5 and 6. P = 2/6 = 1/3.', 'easy', 1, 45),

-- Matrices and Series (46-50)
('q_em_2023_046', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The determinant of matrix [[2, 3], [1, 4]] is:', 'multiple_choice', '["A. 5", "B. 8", "C. 11", "D. -5"]', 'A', 'det = (2)(4) - (3)(1) = 8 - 3 = 5.', 'easy', 1, 46),
('q_em_2023_047', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The sum of the first 10 terms of AP: 2, 5, 8, ... is:', 'multiple_choice', '["A. 155", "B. 145", "C. 165", "D. 135"]', 'A', 'a = 2, d = 3. S₁₀ = 10/2[2(2) + 9(3)] = 5[4 + 27] = 5(31) = 155.', 'medium', 1, 47),
('q_em_2023_048', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The 5th term of GP: 2, 6, 18, ... is:', 'multiple_choice', '["A. 54", "B. 162", "C. 486", "D. 324"]', 'B', 'a = 2, r = 3. T₅ = ar⁴ = 2 × 3⁴ = 2 × 81 = 162.', 'medium', 1, 48),
('q_em_2023_049', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'For a 2×2 matrix A, if det(A) = 0, then A is:', 'multiple_choice', '["A. Invertible", "B. Singular", "C. Identity", "D. Diagonal"]', 'B', 'A matrix with determinant 0 is singular (non-invertible).', 'easy', 1, 49),
('q_em_2023_050', 'subj_wassce_elect_math', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_em_2023_1', 'The sum to infinity of GP: 1, 1/2, 1/4, ... is:', 'multiple_choice', '["A. 1", "B. 2", "C. 3", "D. 4"]', 'B', 'S∞ = a/(1-r) = 1/(1-0.5) = 1/0.5 = 2.', 'medium', 1, 50);
